        sst = math.fsum(sst_terms)
    except (OverflowError, ValueError) as exc:
        raise non_finite() from exc
    if not math.isfinite(sst):
        raise non_finite()

    if sst != 0:
        try:
            result = 1.0 - sse / sst
        except (OverflowError, ValueError) as exc:
            raise non_finite() from exc
        if not math.isfinite(result):
            raise non_finite()
        if result == 0:
            return 0.0
        return result
    if sse == 0:
        return 1.0
    if force_finite:
        return 0.0
    return float("-inf")


